"""CUDA source strings for Walsh, RX and apply_X. Not compiled at import."""
WALSH = 'extern "C" __global__\nvoid walsh_qubit(const double2* src, double2* dst,\n                 long long batch, long long dim, long long step) {\n    long long n_pairs = dim >> 1;\n    long long total = batch * n_pairs;\n    long long tid = (long long)blockDim.x * blockIdx.x + threadIdx.x;\n    if (tid >= total) return;\n    long long b = tid / n_pairs;\n    long long p = tid - b * n_pairs;\n    long long blk = p / step;\n    long long off = p - blk * step;\n    long long i0 = b * dim + blk * (step << 1) + off;\n    long long i1 = i0 + step;\n    double2 a = src[i0];\n    double2 d = src[i1];\n    const double s = sqrt(2.0);\n    double2 e, o;\n    e.x = (a.x + d.x) / s;\n    e.y = (a.y + d.y) / s;\n    o.x = (a.x - d.x) / s;\n    o.y = (a.y - d.y) / s;\n    dst[i0] = e;\n    dst[i1] = o;\n}\n'
RX = 'extern "C" __global__\nvoid rx_qubit(const double2* src, double2* dst, const double* beta,\n              long long batch, long long dim, long long step, int beta_scalar) {\n    long long n_pairs = dim >> 1;\n    long long total = batch * n_pairs;\n    long long tid = (long long)blockDim.x * blockIdx.x + threadIdx.x;\n    if (tid >= total) return;\n    long long b = tid / n_pairs;\n    long long p = tid - b * n_pairs;\n    long long blk = p / step;\n    long long off = p - blk * step;\n    long long i0 = b * dim + blk * (step << 1) + off;\n    long long i1 = i0 + step;\n    double ang = beta_scalar ? beta[0] : beta[b];\n    double c = cos(ang);\n    double sn = sin(ang);\n    double2 a = src[i0];\n    double2 d = src[i1];\n    double2 e, o;\n    e.x = c * a.x + sn * d.y;\n    e.y = c * a.y - sn * d.x;\n    o.x = c * d.x + sn * a.y;\n    o.y = c * d.y - sn * a.x;\n    dst[i0] = e;\n    dst[i1] = o;\n}\n'
APPLYX = 'extern "C" __global__\nvoid apply_X_fused(const double2* v, double2* out,\n                   long long batch, long long dim, int n) {\n    long long total = batch * dim;\n    long long tid = (long long)blockDim.x * blockIdx.x + threadIdx.x;\n    if (tid >= total) return;\n    long long b = tid / dim;\n    long long s = tid - b * dim;\n    const double2* row = v + b * dim;\n    double accx = 0.0, accy = 0.0;\n    for (int q = 0; q < n; ++q) {\n        long long t = s ^ (((long long)1) << q);\n        double2 u = row[t];\n        accx += u.x;\n        accy += u.y;\n    }\n    out[tid].x = accx;\n    out[tid].y = accy;\n}\n'
